    for n in nodes: d[n][n]=0
    for i in nodes:
        for j,w in a[i].items(): d[i][j]=w
    for k in nodes:
        for i in nodes:
            if d[i][k]==INF: continue
            for j in nodes:
                if d[i][k]+d[k][j]<d[i][j]: d[i][j]=d[i][k]+d[k][j]
    return d

def norm(routers):
    return {(r,ds):(e["nextHop"],e["metric"]) for r,row in routers.items() for ds,e in row.items()}

