        else:
            events.append({"time":t,"action":act,"from":x,"to":y}); p=(x,y) if x<y else (y,x)
            (disabled.add if act=="link-down" else disabled.discard)(p)
    infm=max((e["metric"] for e in links),default=0)+rng.choice([1,2,6,40])
    hd=rng.choice([None,0,1,2,4])
    base={"infinityMetric":infm,"events":events}
    if hd is not None: base["holdDownRounds"]=hd
    off=replay_dv_scenario(topo,base)
    on=replay_dv_scenario(topo,{**base,"poisonReverse":True})
    fold_down,fold_dis=set(),set()
    states=[(frozenset(),frozenset())]
    for e in events:
