        states.append((frozenset(fold_down),frozenset(fold_dis)))
    for i,(eo,en) in enumerate(zip(off["timeline"],on["timeline"])):
        fo=norm(eo["rounds"][-1]["routers"]); fn=norm(en["rounds"][-1]["routers"])
        if fo!=fn:
